 "content": "def transform(grid):
    """Connect the horizontally aligned marker pair with an orthogonal 3-path."""
    out = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    rows = {}
    for r, c in markers:
        rows.setdefault(r, []).append(c)
    spine_rows = [r for r, cols in rows.items() if len(cols) >= 2]
    if not spine_rows:
        return out
    # The aligned pair forms the horizontal trunk; other markers join it vertically.
    trunk = spine_rows[0]
    left, right = min(rows[trunk]), max(rows[trunk])
    for c in range(left + 1, right):
        if out[trunk][c] == 0:
            out[trunk][c] = 3
    for r, c in markers:
        if r == trunk:
            continue
        step = 1 if trunk > r else -1
        for rr in range(r + step, trunk, step):
            if out[rr][c] == 0:
                out[rr][c] = 3
    return out
